import { 
  type ParsedGearItem, 
  type GearParseResult, 
  validateParsedGearItem 
} from './index'

function decodeHtmlEntities(text: string): string {
  const entityMap: Record<string, string> = {
    '&amp;': '&',
    '&lt;': '<',
    '&gt;': '>',
    '&quot;': '"',
    '&#x27;': "'",
    '&#x2F;': '/',
    '&#x3D;': '=',
    '&#x60;': '`'
  }

  return text.replace(/&(?:#x[0-9a-fA-F]+|#[0-9]+|[a-zA-Z0-9]+);/g, (entity) => {
    // Handle named entities
    if (entityMap[entity]) {
      return entityMap[entity]
    }

    // Handle numeric entities like &#47; (/)
    if (entity.startsWith('&#') && entity.endsWith(';')) {
      const numStr = entity.slice(2, -1)
      let charCode: number

      if (numStr.startsWith('x')) {
        // Hexadecimal
        charCode = parseInt(numStr.slice(1), 16)
      } else {
        // Decimal
        charCode = parseInt(numStr, 10)
      }

      if (!isNaN(charCode)) {
        return String.fromCharCode(charCode)
      }
    }

    // Return original entity if we can't decode it
    return entity
  })
}

