          <div className="text-center p-2 bg-orange-50 rounded-lg border">
            <div className="text-lg font-semibold text-orange-700">{duplicates.length}</div>
            <div className="text-xs text-orange-600">Duplicates</div>
          </div>
          <div className="text-center p-2 bg-blue-50 rounded-lg border">
            <div className="text-lg font-semibold text-blue-700">{formatWeightForDisplay(newItemsWeight)}</div>
            <div className="text-xs text-blue-600">Weight</div>
          </div>
          <div className="text-center p-2 bg-purple-50 rounded-lg border">
            <div className="text-lg font-semibold text-purple-700">{newCategories.size}</div>
            <div className="text-xs text-purple-600">Categories</div>
          </div>
        </div>

        {/* New Items Table */}
        {newItems.length > 0 && (
          <div className="space-y-2">
            <h4 className="font-medium text-sm">New Items to Import</h4>
            <div className="max-h-48 overflow-y-auto">
              <GearTable
                items={newItemsForTable}
                viewMode="compact"
                weightUnit="g" // Show in grams for now (could be made configurable)
                onEdit={() => {}} // No editing in preview
                onDelete={() => {}} // No deleting in preview
                showActions={false}
              />
            </div>
          </div>
        )}

        {/* Duplicates Preview */}
        {duplicates.length > 0 && (
          <div>
            <h4 className="font-medium mb-2 text-orange-600 text-sm">Duplicate Items (skipped)</h4>
            <div className="space-y-1 max-h-24 overflow-y-auto">
              {duplicates.slice(0, 2).map((item, i) => (
                <div key={i} className="flex items-center justify-between p-2 bg-orange-50 border border-orange-200 rounded text-xs">
                  <div className="flex-1 truncate">
                    <div className="font-medium text-orange-800 truncate">{item.description}</div>
                    <div className="text-orange-600">
                      {item.item_type} • {formatWeightWithUnit(item.weight_g, item.weight_unit_display)}
                    </div>
                  </div>
                  <span className="text-xs bg-orange-200 text-orange-800 px-1 py-0.5 rounded flex-shrink-0">Duplicate</span>
                </div>
              ))}
              {duplicates.length > 2 && (
                <div className="text-center text-xs text-orange-600 py-1">
                  ... and {duplicates.length - 2} more
                </div>
              )}
            </div>
          </div>
        )}

        {/* Import Error */}
        {importError && (
          <Alert variant="destructive">
            <AlertCircle className="h-4 w-4" />
            <AlertDescription>
              <div className="font-medium mb-2">Import Failed:</div>
              <div className="text-sm">{importError}</div>
            </AlertDescription>
          </Alert>
        )}

        {/* Actions */}
        <div className="flex justify-center gap-3 pt-4">
          {newItems.length > 0 ? (
            <>
              <Button onClick={handleImport} disabled={isImporting}>
                {isImporting ? (
                  <>
                    <Loader2 className="h-4 w-4 mr-2 animate-spin" />
                    Importing...
                  </>
                ) : (
                  `Import ${newItems.length} New Items`
                )}
              </Button>
              <Button variant="outline" onClick={onCancel} disabled={isImporting}>
                Back
              </Button>
            </>
          ) : (
            <Button variant="outline" onClick={onCancel}>
              Back to Import
            </Button>
          )}
        </div>
      </CardContent>
    </Card>
  )
}

import { useState, useEffect } from 'react'
import { useAuth } from '@/contexts/AuthContext'
import { createGearRepository } from '@/lib/gearRepository'
import { Button } from '@/components/ui/button'
import { Card, CardContent, CardDescription, CardHeader, CardTitle } from '@/components/ui/card'
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs'
import { Upload, Link } from 'lucide-react'
import { CsvImport } from './CsvImport'
import { UrlImport } from './UrlImport'
import { ImportPreview } from './ImportPreview'
import type { ParsedGearItem } from '@/utils/parser'
import type { GearItem } from '@/types/database'

interface ImportGearFormProps {
  onCancel?: () => void
  className?: string
}

export interface ImportState {
  step: 'input' | 'preview'
  items: ParsedGearItem[]
  newItems: ParsedGearItem[]
  duplicates: ParsedGearItem[]
  errors: string[]
  warnings: string[]
  metadata?: {
    listName?: string
    totalWeight?: number
    itemCount?: number
  }
}

export function ImportGearForm({ onCancel, className }: ImportGearFormProps) {
  const { user } = useAuth()
  const [activeTab, setActiveTab] = useState<'csv' | 'url'>('url')
  const [existingItems, setExistingItems] = useState<GearItem[]>([])
  const [importState, setImportState] = useState<ImportState>({
    step: 'input',
    items: [],
    newItems: [],
    duplicates: [],
    errors: [],
    warnings: []
  })

  // Fetch existing gear items on mount
  useEffect(() => {
    const fetchExistingItems = async () => {
      if (!user) return

      try {
        const gearRepository = createGearRepository(user.id)
        const items = await gearRepository.list()
        setExistingItems(items)
      } catch (error) {
        console.error('Failed to fetch existing gear items:', error)
      }
    }

    fetchExistingItems()
  }, [user])

  // Function to check if two items are duplicates
  const isDuplicate = (importItem: ParsedGearItem, existingItem: GearItem): boolean => {
    // Match on item_type and description (case insensitive)
    const importItemType = importItem.item_type.toLowerCase().trim()
    const importDescription = (importItem.description || '').toLowerCase().trim()
    const existingItemType = existingItem.item_type.toLowerCase().trim()
    const existingDescription = (existingItem.description || '').toLowerCase().trim()

    return importItemType === existingItemType && importDescription === existingDescription
  }

  const handleImportData = (data: ParsedGearItem[], errors: string[] = [], warnings: string[] = [], metadata?: any) => {
    // Deduplicate against existing items
    const newItems: ParsedGearItem[] = []
    const duplicates: ParsedGearItem[] = []

    data.forEach(importItem => {
      const isDuplicateItem = existingItems.some(existing => isDuplicate(importItem, existing))
      if (isDuplicateItem) {
        duplicates.push(importItem)
      } else {
        newItems.push(importItem)
      }
    })

    // Add deduplication warnings (summary only, no ugly lists)
    const updatedWarnings = [...warnings]
    if (duplicates.length > 0) {
      updatedWarnings.push(
        `${duplicates.length} items skipped as duplicates (already exist in your gear library)`
      )
    }

    if (newItems.length > 0) {
      updatedWarnings.push(`${newItems.length} new items ready to import`)
    }

    setImportState({
      step: 'preview', // Always show preview, even if no new items
      items: data,
      newItems,
      duplicates,
      errors,
      warnings: updatedWarnings,
      metadata
    })
  }


  const handleReset = () => {
    setImportState({
      step: 'input',
      items: [],
      newItems: [],
      duplicates: [],
      errors: [],
      warnings: [],
      metadata: undefined
    })
  }

  const handleClose = () => {
    handleReset()
    onCancel?.()
  }

  if (importState.step === 'preview') {
    return (
      <ImportPreview
        items={importState.items}
        newItems={importState.newItems}
        duplicates={importState.duplicates}
        errors={importState.errors}
        warnings={importState.warnings}
        metadata={importState.metadata}
        onCancel={handleReset}
        className={className}
      />
    )
  }


  return (
    <Card className={className}>
      <CardHeader>
        <CardTitle>Import Gear</CardTitle>
        <CardDescription>
          Import your gear from LighterPack by URL or CSV file
        </CardDescription>
      </CardHeader>
      <CardContent>
        <Tabs defaultValue="url" value={activeTab} onValueChange={(value) => setActiveTab(value as 'csv' | 'url')}>
          <TabsList className="grid w-full grid-cols-2">
            <TabsTrigger value="url" className="flex items-center gap-2">
              <Link className="h-4 w-4" />
              LighterPack URL
            </TabsTrigger>
            <TabsTrigger value="csv" className="flex items-center gap-2">
              <Upload className="h-4 w-4" />
              CSV File
            </TabsTrigger>
          </TabsList>

          <TabsContent value="url" className="mt-6">
            <UrlImport onImportData={handleImportData} />
          </TabsContent>

          <TabsContent value="csv" className="mt-6">
            <CsvImport onImportData={handleImportData} />
          </TabsContent>
        </Tabs>

        <div className="flex justify-end gap-2 mt-6 pt-4 border-t">
          <Button variant="ghost" onClick={handleClose}>
            Cancel
          </Button>
        </div>
      </CardContent>
    </Card>
  )
}

